Given two nonempty sets $X,Y\subset M$,
the \emph{Pompeiu excess\/} ({\it {\'e}cart}, in French) {\it of $X$ over $Y$}
 is defined by (\cite[pp.~281--282]{Pomp}, \cite[Chapter~II]{CV})
  \begin{equation*}
e(X,Y)\equiv e_d(X,Y):=\sup_{x\in X}d(x,Y)=\inf\{r>0:X\subset\mathcal{O}_r(Y)\},
  \end{equation*}
where $d(x,Y):=\inf_{y\in Y}d(x,y)$ is the distance\footnote{$d(x,\varnothing):=+\infty.$}
from $x\in M$ to $Y$,
and the set $\mathcal{O}_r(Y):=\{x\in M:d(x,Y)<r\}$ is the open $r$-neighbourhood
\footnote{$\mathcal{O}_r(\varnothing)\!:=\!\varnothing$ for $r>0$; $e(\varnothing,Y):=0$ for any $Y\subset M$,
and $e(X,\varnothing):=+\infty$ if $\varnothing\!\ne\! X\!\subset\! M$.}
of~$Y$, $r>0$ (if $Y=\{y\}$,
$\mathcal{O}_r(y)\equiv\mathcal{O}_r(Y)$ is simply the open ball of radius $r$ centered at $y\in M$).

The well-known properties of $e(\cdot,\cdot)$ are as follows. Given $X,Y,Z\subset M$:
\par\vspace{2pt}
(a) $e(X,Y)\!=\!0$ iff\footnote{`iff' means as usual `if and only if'.} $X\!\subset\!\ov{Y}$,
where $\ov{Y}\!=\!\bigcap_{r>0}\mathcal{O}_r(Y)$ is the closure of $Y$~in~$M$;
\par\vspace{2pt}
(b) $e(X,Y)\le e(X,Z)+e(Z,Y)$ (triangle inequality for~$e$);
\par\vspace{2pt}
(c) $e(X,Y)<+\infty$ provided $X$ and $Y$ are bounded (and, in particular bounded
and closed, or compact).

The \emph{Pompeiu-Hausdorff distance\/} between two sets $X,Y\subset M$
 is defined by (e.g., \cite{Pomp}, \cite[Chapter~II]{CV})
\footnote{Pompeiu \cite{Pomp} symmetrized the excess $e$ by
 $d_P(X,Y)\!:=\!e(X,Y)\!+\!e(Y,X)$ (cf. also~\cite{Ber-Pac}).}
  \begin{equation*}
d_H(X,Y)\!:=\max\{e(X,Y),e(Y,X)\}\!=\!
\inf\{r\!>\!0:\mbox{$X\!\subset\!\mathcal{O}_r(Y)$\,and\,$Y\!\subset\!\mathcal{O}_r(X)$}\}.
  \end{equation*}

Of main interest in this paper are multifunctions $F:T\to\mbox{c}(M)$
with $T$ a nonempty subset of the reals $\mathbb{R}$. Such an $F$ is said to be
\emph{of bounded variation\/} (with respect to~$d_H$) provided its (total)
 \emph{Jordan variation\/}
  \begin{equation*}
\mbox{\rm V}(F,T)\!:=\sup_\pi\sum_{i=1}^m d_H\bigl(F(t_{i-1}),F(t_i)\bigr)\quad
\mbox{is finite\quad ($\mbox{\rm V}(F,\varnothing):=0$),}
  \end{equation*}
the supremum being taken over all partitions $\pi$ of the set $T\subset\mathbb{R}$, i.e.,
$m\in\mathbb{N}$ and $\pi=\{t_i\}_{i=0}^m\subset T$ such that $t_{i-1}\le t_i$
for all $i\in\{1,\dots,m\}$.

In order to do it, given $F:T\to\mbox{c}(M)$, following \cite{JMAA07} the quantities
  \begin{equation*}
{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T)\!:=\!\sup_\pi\sum_{i=1}^m e\bigl(F(t_{i-1}\!),F(t_i)\bigr)
\mbox{ and \,}
{\scriptstyle\overleftarrow{\mbox{\rm V}}}(F,T)\!:=\!\sup_\pi\sum_{i=1}^m e\bigl(F(t_i),F(t_{i-1}\!)\bigr)
  \end{equation*}
are said to be the \emph{directional\/} (or \emph{excess\/}) \emph{variations of $F$
to the right\/} and \emph{to the left}, respectively (${\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,\varnothing)={\scriptstyle\overleftarrow{\mbox{\rm V}}}(F,\varnothing):=0$).

Clearly,
  \begin{equation*}
\max\bigl\{{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T),{\scriptstyle\overleftarrow{\mbox{\rm V}}}(F,T)\bigr\}\le\mbox{\rm V}(F,T)\le{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T)+{\scriptstyle\overleftarrow{\mbox{\rm V}}}(F,T),
  \end{equation*}
and so, $\mbox{\rm V}(F,T)$ is finite iff both ${\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T)$ and ${\scriptstyle\overleftarrow{\mbox{\rm V}}}(F,T)$ are finite.

Since $(\mbox{c}(M),d_H)$ is a metric space, it is known (e.g., \cite[2.19]{Var},
\cite{JDCS}, \cite{MatSb}) that $\mbox{\rm V}$ is \emph{additive\/} (in the second variable)
in the sense that
  \begin{equation} \mbox{\rm V}(F,T)=\mbox{\rm V}(F,T_{(-\infty,t]})+\mbox{\rm V}(F,T_{[t,+\infty)})\quad\mbox{for all \,\,$t\in T$.}
  \end{equation}

For any $n\in\mathbb{N}$ and $s,t\in T$, the triangle inequality for $e$ implies
  \begin{equation*}
|e(F_n(s),F_n(t))-e(F(s),F(t))|\le d_H(F_n(s),F(s))+d_H(F_n(t),F(t)),
  \end{equation*}
and so, by the pointwise convergence of $F_n$ to $F$, $e(F_n(s),F_n(t))\!\to\! e(F(s),F(t))$
as $n\to\infty$. Given $m\in\mathbb{N}$ and a partition $\pi=\{t_i\}_{i=0}^m$ of $T$,
by definition of~${\scriptstyle\overrightarrow{\mbox{\rm V}}}$,
  \begin{equation*}
\sum_{i=1}^m e(F_n(t_{i-1}),F_n(t_i))\le{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F_n,T)\quad\mbox{for all \,\,$n\in\mathbb{N}$.}
  \end{equation*}
Passing to the limit inferior as $n\to\infty$, we get
  \begin{equation*}
\sum_{i=1}^m e(F(t_{i-1}),F(t_i))\le\liminf_{n\to\infty}{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F_n,T),
  \end{equation*}
and it remains to take the supremum over all partitions $\pi$ of $T$.
\qed

By virtue of \cite[Lemma~4.2]{MatSb}, the following two assertions hold.

\begin{itemize}
\item[{\rm(a)}] If $t\in T$ is a left limit point of $T$ and $\mbox{\rm V}(F,T)<+\infty$, then
  \begin{equation} v(t)=v(t-0)+\lim_{T\ni s\to t-0}d_H(F(s),F(t)).
\footnote{$v(t-0):=\lim_{T\ni s\to t-0}v(s)$ is the left limit of $v$ at $t$ along $T$,
i.e., $v(t-0)$ is the limit of $v(s)$ as $s\to t$ with $s\in T_{(-\infty,t)}$.}
  \end{equation}
\item[{\rm(b)}] If $t\in T$ is a right limit point of $T$ and $\mbox{\rm V}(F,T)<+\infty$, then
  \begin{equation} v(t+0)=v(t)+\lim_{T\ni s\to t+0}d_H(F(s),F(t)).
\footnote{$v(t+0):=\lim_{T\ni s\to t+0}v(s)=
  \lim_{s\to t,s\in T_{(t,+\infty)}}v(s)$ is the right limit of $F$ at~$t$.}
  \end{equation}
\end{itemize}

If $t\in T$ is a left limit point of $T$, then
\footnote{The limit superior in ($\ori{\mbox{\rm a}}$) is the limit of
$\sup\{e(F(s),F(t)):s\in T_{(t-\varepsilon,t)}\}$ as $\varepsilon\to+0$;
in ($\ole{\mbox{\rm a}}$) the limit superior is understood similarly.}
  \begin{itemize}
\item[${\rm(\ori{\mbox{\rm a}})}$] $\ori{v}(t)=\ori{v}(t-0)+\displaystyle
  \limsup_{T\ni s\to t-0}e(F(s),F(t))$ \,if \,\,${\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T)<+\infty;$
\item[${\rm(\ole{\mbox{\rm a}})}$] $\ole{v}(t)=\ole{v}(t-0)+\displaystyle
  \limsup_{T\ni s\to t-0}e(F(t),F(s))$ \,if \,\,${\scriptstyle\overleftarrow{\mbox{\rm V}}}(F,T)<+\infty.$
  \end{itemize}

If $t\in T$ is a right limit point of $T$, then
\footnote{The limit superior in ($\ori{\mbox{\rm b}}$) is the limit of
$\sup\{e(F(t),F(s)):s\in T_{(t,t+\varepsilon)}\}$ as $\varepsilon\to+0$;
the limit superior in ($\ole{\mbox{\rm b}}$) has a similar meaning.}
  \begin{itemize}
\item[${\rm(\ori{\mbox{\rm b}})}$] $\ori{v}(t+0)=\ori{v}(t)+\displaystyle
  \limsup_{T\ni s\to t+0}e(F(t),F(s))$ \,if \,\,${\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T)<+\infty;$
\item[${\rm(\ole{\mbox{\rm b}})}$] $\ole{v}(t+0)=\ole{v}(t)+\displaystyle
  \limsup_{T\ni s\to t+0}e(F(s),F(t))$ \,if \,\,${\scriptstyle\overleftarrow{\mbox{\rm V}}}(F,T)<+\infty.$
  \end{itemize}

As in the proof of Lemma~\ref{l:jumps}, we concentrate 
on ($\ori{\mbox{\rm a}}$) and ($\ori{\mbox{\rm b}}$).

($\ori{\mbox{\rm a}}$) This is a consequence of Lemma~\ref{l:jumps}
($\ori{\mbox{\rm a}}$), since ${\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{(-\infty,t]})=\ori{v}(t)$ and,
by virtue of \mbox{\rm(\ref{e:ttos})}, ${\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{(-\infty,t)})=\ori{v}(t-0)$.

($\ori{\mbox{\rm b}}$) For every $s\in T_{(t,+\infty)}$, the additivity of ${\scriptstyle\overrightarrow{\mbox{\rm V}}}$ implies
  \begin{equation*}
{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{[t,+\infty)})=\ori{v}(s)-\ori{v}(t)+{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{[s,+\infty)}).
  \end{equation*}
Passing to the limit as $T\ni s\to t+0$, we get: by Lemma~\ref{l:jumps}
($\ori{\mbox{\rm b}}$),
  \begin{equation*}
\ori{v}(s)-\ori{v}(t)\to\ori{v}(t+0)-\ori{v}(t)=\limsup_{T\ni s\to t+0}e(F(t),F(s)),
  \end{equation*}
and by \mbox{\rm(\ref{e:ttoi})}, ${\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{[s,+\infty)})\to{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{(t,+\infty)})$.
\qed

Given $F:T\to\mbox{c}(M)$, its \emph{modulus of variation\/} is the nondecreasing
sequence $\{\nu_k(F,T)\}_{k=1}^\infty\subset[0,+\infty]$ defined by
  \begin{equation*}
\nu_k(F,T)\!:=\sup\,\sum_{i=1}^k d_H(F(s_i),F(t_i)),
  \end{equation*}
the supremum being taken over all collections $s_1,\dots,s_k,t_1\dots,t_k$ of $2k$
numbers from $T$ such that $s_1\le t_1\le s_2\le t_2\le\dots\le s_{k-1}\le t_{k-1}
\le s_k\le t_k$.

Making use of an idea from \cite[Example~3.1]{JMAA07}, here we present an example
of a multifunction $F:T\to\mbox{c}(M)$ with $T:=[0,1]$ such that
${\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T)<+\infty$ and ${\scriptstyle\overleftarrow{\mbox{\rm V}}}(F,T)=+\infty$ (thus, Theorem~\ref{t:BV}(a) is
applicable to $F$, whereas Theorem~\ref{t:A} is not).

Let $N\in\mathbb{N}$ and $\{\alpha_n\}_{n=1}^\infty\subset(0,+\infty)$ be a
decreasing sequence such that
  \begin{equation} \lim_{n\to\infty}\alpha_n=0\quad\mbox{and}\quad
\sum_{n=1}^\infty\alpha_{nN}=+\infty
  \end{equation}
(e.g., $\alpha_n=1/n$). Given $n\in\mathbb{N}$, we set
  \begin{equation*}
X_n:=\{0\}\cup\{\alpha_iu_i:1\le i\le nN\},\quad\mbox{and}\quad
X_\infty:=\{0\}\cup\{\alpha_iu_i:i\in\mathbb{N}\}.
  \end{equation*}
Clearly, $X_n\in\mbox{c}(M)$ for all $n\in\mathbb{N}$ and, by the first assumption in \mbox{\rm(\ref{e:Alph})},
the set $X_\infty$ is compact as well. Let $\{\tau_n\}_{n=0}^\infty\subset[0,1)$ be a
strictly increasing sequence such that $\tau_0=0$ and $\lim_{n\to\infty}\tau_n=1$.
Define $F:T\to\mbox{c}(M)$ by the rule:
  \begin{equation*}
\mbox{$F(t):=X_n$ \,if\, $\tau_{n-1}\le t<\tau_n$ for all $n\in\mathbb{N}$, \,and\,
$F(1):=X_\infty$.}
  \end{equation*}
Since $X_n\subset X_{n+1}\subset X_\infty$ for all $n\in\mathbb{N}$, $F$ is nondecreasing
on $T$ (Section~\ref{ss:mon}), and so, ${\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T)=0$. In order to see that
${\scriptstyle\overleftarrow{\mbox{\rm V}}}(F,T)=+\infty$, given $m\in\mathbb{N}$, $m\ge2$, and partition
$\pi_m=\{\tau_n\}_{n=0}^{m-1}\cup\{1\}$ of $T=[0,1]$, we find
  \begin{align}
{\scriptstyle\overleftarrow{\mbox{\rm V}}}(F,T)&\ge\sum_{n=1}^{m-1}e(F(\tau_n),F(\tau_{n-1}))+e(F(1),F(\tau_{m-1}))
  \nonumber\\
&=\sum_{n=1}^{m-1}e(X_{n+1},X_n)+e(X_\infty,X_m), \end{align}
where
  \begin{equation*}
e(X_{n+1},X_n)=\sup_{nN+1\le k\le(n+1)N}\Bigl(|\alpha_k|+
  \inf_{1\le i\le nN}|\alpha_i|\Bigr)=\alpha_{nN+1}+\alpha_{nN}
  \end{equation*}
and
  \begin{equation*}
e(X_\infty,X_m)=\sup_{k\ge mN+1}\Bigl(|\alpha_k|+
  \inf_{1\le i\le mN}|\alpha_i|\Bigr)=\alpha_{mN+1}+\alpha_{mN}.
  \end{equation*}
It follows that the quantity \mbox{\rm(\ref{e:rhs})} is equal to
  \begin{equation*}
\sum_{n=1}^m\alpha_{nN+1}+\sum_{n=1}^m\alpha_{nN}\to+\infty\quad
\mbox{as}\quad m\to\infty.
  \end{equation*}

Suppose a multifunction $F:T\!\times\!\mbox{\rm c}(M)\!\to\!\mbox{\rm c}(M)$
is such that\/{\rm:}
  \begin{itemize}
\item[{\rm(a)}] there is a nondecreasing bounded function $\varphi:T\to\mathbb{R}$ such that
  \begin{equation*}
\mbox{$\!\!\!e(F(s,X),F(t,X))\le\varphi(t)-\varphi(s)$ for all $s,t\in T$, $s\le T$, and
  $X\in\mbox{\rm c}(M);$}
  \end{equation*}
\item[{\rm(b)}] there is a number $0\le\mu<1$ such that
  \begin{equation*}
\mbox{$e(F(t,X),F(t,Y))\le\mu d_H(X,Y)$ for all $t\in T$ and $X,Y\in\mbox{\rm c}(M);$}
  \end{equation*}
\item[{\rm(c)}] there is a multifunction $K:T\to\mbox{\rm c}(M)$ such that
  \begin{equation*}
\mbox{$F(t,X)\subset K(t)$ for all $t\in T$ and $X\in\mbox{\rm c}(M)$.}
  \end{equation*}
  \end{itemize}

If $t_0:=\inf T\in T$ and $X_0\in\mbox{\rm c}(M)$, then there is
$X:T\to\mbox{\rm c}(M)$ such that\\[3pt]
{\rm(i)}~$\mbox{\rm V}(X,T)\le\mbox{\rm V}(\varphi,T)/(1-\mu)<+\infty;$
{\rm(ii)}~$X(t)\subset F(t,X(t))$ for all $t\in T;$\\[3pt]
{\rm(iii)} $d_H(X_0,X(t_0))\le e\bigl(X_0,F(t_0,X(t_0))\bigr)$.
\smallbreak
In addition, if $X_0\subset F(t_0,X_0)$, then {\rm(iii)} can be replaced by $X(t_0)=X_0$.

The purpose of this example is to show that assumptions of Theorem~\ref{t:FuEm}
can be fulfiled. Let $M=\mathbb{B}$ be a Banach space with norm $|\cdot|$ and
metric $d(x,y)=|x-y|$, $x,y\in M$, and $K\in\mbox{c}(M)$. Suppose
$\varphi_0:T\to[0,+\infty)$ is nondecreasing and $\mu\!:=\!\sup_{t\in T}\varphi_0(t)<1$.
Define $F:T\times\mbox{c}(M)\to\mbox{c}(M)$ by $F(t,X):=\varphi_0(t)X$ for
$t\in T$ and $X\in\mbox{c}(M)$. We have
  \begin{equation*}
e(F(s,X),F(t,X))\le\bigl(\varphi_0(t)-\varphi_0(s)\bigr)\max_{x\in X}|x|\quad
\mbox{for all $s,t\in T$, $s\le t$,} 
  \end{equation*}
and so, condition (a) in Theorem~\ref{t:FuEm} is satisfied with
$\varphi(t)\!:=\!\varphi_0(t)\max_{x\in K}|x|$, $t\in T$, for all $X\in\mbox{c}(K)$.
Furthermore, given $t\in T$ and $X,Y\in\mbox{c}(K)\subset\mbox{c}(M)$,
  \begin{equation*}
e(F(t,X),F(t,Y))=\varphi_0(t)e(X,Y)\le\mu d_H(X,Y),
  \end{equation*}
and so, condition (b) in Theorem~\ref{t:FuEm} is satisfied. Finally, setting
$K(t):=\varphi_0(t)K$, we find $F(t,X)\subset K(t)$ for all $t\in T$
and $X\in\mbox{c}(K)$.

J_a(\Gamma,t_0):=\left\{
  \begin{array}{ccc}
d_H(\Gamma(s_0),\Gamma(t_0)), & \,\,\mbox{if}\,\,\, & s_0\in T_{[a,t_0)},\\[4pt]
\displaystyle\lim_{T\ni t\to s_0-0}\!\mbox{\rm V}(\Gamma,T_{[t,t_0]}),
  & \,\,\mbox{if}\,\,\, & s_0\notin T_{[a,t_0)}.
  \end{array}\right.

v(t)=v(t-0)+\lim_{T\ni s\to t-0}d_H(F(s),F(t)).
\footnote{$v(t-0):=\lim_{T\ni s\to t-0}v(s)$ is the left limit of $v$ at $t$ along $T$,
i.e., $v(t-0)$ is the limit of $v(s)$ as $s\to t$ with $s\in T_{(-\infty,t)}$.}

v(t+0)=v(t)+\lim_{T\ni s\to t+0}d_H(F(s),F(t)).
\footnote{$v(t+0):=\lim_{T\ni s\to t+0}v(s)=
  \lim_{s\to t,s\in T_{(t,+\infty)}}v(s)$ is the right limit of $F$ at~$t$.}

Since $\{t_i\}_{i=0}^m\cup\{s_j\}_{j=0}^n$ is a partition of $T$, we get, from \mbox{\rm(\ref{e:xi1})},
$\xi+\eta<{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T)$, which, due to the arbitrariness of $\xi$ and $\eta$ as above,
implies the inequality
  \begin{equation*}
{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{(-\infty,t]})+{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{[t,+\infty)})\le{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T).
  \end{equation*}

($\Rightarrow\!$) Let $\ori{v}(t)={\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{(-\infty,t]})$, $t\in T$, be the variation
function (to the right) of~$F$. It is nondecreasing on $T$ and bounded:
$\sup_{t\in T}\ori{v}(t)\le{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T)$. Given $s,t\in T$, $s\le t$, the additivity
of ${\scriptstyle\overrightarrow{\mbox{\rm V}}}$ implies
  \begin{equation*}
e(F(s),F(t))\le{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{[s,t]})={\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{(-\infty,t]})-{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{(-\infty,s]})
=\ori{v}(t)-\ori{v}(s).
  \end{equation*}
It remains to set $\varphi:=\ori{v}$.

For any $n\in\mathbb{N}$ and $s,t\in T$, the triangle inequality for $e$ implies
  \begin{equation*}
|e(F_n(s),F_n(t))-e(F(s),F(t))|\le d_H(F_n(s),F(s))+d_H(F_n(t),F(t)),
  \end{equation*}
and so, by the pointwise convergence of $F_n$ to $F$, $e(F_n(s),F_n(t))\!\to\! e(F(s),F(t))$
as $n\to\infty$.

Given $m\in\mathbb{N}$ and a partition $\pi=\{t_i\}_{i=0}^m$ of $T$,
by definition of~${\scriptstyle\overrightarrow{\mbox{\rm V}}}$,
  \begin{equation*}
\sum_{i=1}^m e(F_n(t_{i-1}),F_n(t_i))\le{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F_n,T)\quad\mbox{for all \,\,$n\in\mathbb{N}$.}
  \end{equation*}

Passing to the limit inferior as $n\to\infty$, we get
  \begin{equation*}
\sum_{i=1}^m e(F(t_{i-1}),F(t_i))\le\liminf_{n\to\infty}{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F_n,T),
  \end{equation*}
and it remains to take the supremum over all partitions $\pi$ of $T$.
\qed

($\ori{\mbox{\rm a}}$)
First, we prove inequality $\ge$ in ($\ori{\mbox{\rm a}}$).
By the additivity of ${\scriptstyle\overrightarrow{\mbox{\rm V}}}$, given $s\in T$ with $s<t$, we have
  \begin{equation*}
\ori{v}(s)+e(F(s),F(t))\le\ori{v}(s)+{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{[s,t]})=\ori{v}(t).
  \end{equation*}
Since $\ori{v}$ is nondecreasing and bounded on $T$ (by ${\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T)$), and $t$ is a left
limit point of $T$, the left limit $\ori{v}(t-0)$ exists in $[0,+\infty)$ and is equal to
$\sup\{\ori{v}(s):s\in T,s<t\}$. Inequality $\ge$ in ($\ori{\mbox{\rm a}}$) follows
now from the properties of the limit superior as $T\!\ni\! s\!\to\! t\!-\!0$, since
the right-hand side in ($\ori{\mbox{\rm a}}$) is equal to
  \begin{equation*}
\lim_{T\ni s\to t-0}\!\ori{v}(s)\!+\!\limsup_{T\ni s\to t-0}\!e(F(s),F(t))\!=\!
\limsup_{T\ni s\to t-0}\!\bigl(\ori{v}(s)\!+\!e(F(s),F(t))\bigr)\le\ori{v}(t).
  \end{equation*}

Now we show that inequality $\le$ holds in ($\ori{\mbox{\rm a}}$). By the definition
of $\ori{v}(t)$, which is finite, for any $\xi\in\mathbb{R}$, $\xi<\ori{v}(t)$, there are $m\in\mathbb{N}$
and a partition $\pi=\{t_i\}_{i=0}^m\cup\{t\}$ of $T_{(-\infty,t]}$ with $t_m<t$
such that
  \begin{equation*}
\xi<\sum_{i=1}^m e(F(t_{i-1}),F(t_i))+e(F(t_m),F(t)).
  \end{equation*}
Given $s\in T_{(t_m,t)}$, the triangle inequality for $e$ implies
  \begin{equation*}
e(F(t_m),F(t))\le e(F(t_m),F(s))+e(F(s),F(t)),
  \end{equation*}
and so, $\xi<\ori{v}(s)+e(F(s),F(t))$. Passing to the limit superior as
$T\ni s\to t-0$, we get
  \begin{equation*}
\xi\le\ori{v}(t-0)+\limsup_{T\ni s\to t-0}e(F(s),F(t)).
  \end{equation*}
It remains to take into account the arbitrariness of $\xi<\ori{v}(t)$.

By the additivity of ${\scriptstyle\overrightarrow{\mbox{\rm V}}}$, given $s\in T$ with $s<t$, we have
  \begin{equation*}
\ori{v}(s)+e(F(s),F(t))\le\ori{v}(s)+{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{[s,t]})=\ori{v}(t).
  \end{equation*}

Now we show that inequality $\le$ holds in ($\ori{\mbox{\rm a}}$). By the definition
of $\ori{v}(t)$, which is finite, for any $\xi\in\mathbb{R}$, $\xi<\ori{v}(t)$, there are $m\in\mathbb{N}$
and a partition $\pi=\{t_i\}_{i=0}^m\cup\{t\}$ of $T_{(-\infty,t]}$ with $t_m<t$
such that
  \begin{equation*}
\xi<\sum_{i=1}^m e(F(t_{i-1}),F(t_i))+e(F(t_m),F(t)).
  \end{equation*}
Given $s\in T_{(t_m,t)}$, the triangle inequality for $e$ implies
  \begin{equation*}
e(F(t_m),F(t))\le e(F(t_m),F(s))+e(F(s),F(t)),
  \end{equation*}
and so, $\xi<\ori{v}(s)+e(F(s),F(t))$. Passing to the limit superior as
$T\ni s\to t-0$, we get
  \begin{equation*}
\xi\le\ori{v}(t-0)+\limsup_{T\ni s\to t-0}e(F(s),F(t)).
  \end{equation*}
It remains to take into account the arbitrariness of $\xi<\ori{v}(t)$.

Given $s\in T_{(t_m,t)}$, the triangle inequality for $e$ implies
  \begin{equation*}
e(F(t_m),F(t))\le e(F(t_m),F(s))+e(F(s),F(t)),
  \end{equation*}
and so, $\xi<\ori{v}(s)+e(F(s),F(t))$.

Passing to the limit superior as
$T\ni s\to t-0$, we get
  \begin{equation*}
\xi\le\ori{v}(t-0)+\limsup_{T\ni s\to t-0}e(F(s),F(t)).
  \end{equation*}
It remains to take into account the arbitrariness of $\xi<\ori{v}(t)$.

($\ori{\mbox{\rm b}}$)
In order to prove inequality $\ge$ in ($\ori{\mbox{\rm b}}$), we make use of the
additivity of ${\scriptstyle\overrightarrow{\mbox{\rm V}}}$ to get
  \begin{equation*}
\ori{v}(t)+e(F(t),F(s))\le\ori{v}(t)+{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{[t,s]})=\ori{v}(s)\quad
\mbox{for all $s\in T_{(t,+\infty)}$.}
  \end{equation*}
Now, it suffices to pass to the limit superior as $T\ni  s\to t+0$.

To show inequality $\le$ in ($\ori{\mbox{\rm b}}$), we apply the additivity property
of ${\scriptstyle\overrightarrow{\mbox{\rm V}}}$ several times. To begin with, note that
  \begin{equation} {\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{[t,+\infty)})={\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T)-\ori{v}(t).
  \end{equation}
Given $\xi\in\mathbb{R}$ with $\xi<{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{[t,+\infty)})$, there exist $m\in\mathbb{N}$ and a
partition $\{t\}\cup\{t_i\}_{i=0}^m$ of $T_{[t,+\infty)}$ with $t<t_0$ such that
  \begin{equation*}
\xi<e(F(t),F(t_0))+\sum_{i=1}^m e(F(t_{i-1}),F(t_i)).
  \end{equation*}
Since, for any $s\!\in\! T_{(t,t_0)}$, $e(F(t),F(t_0))\!\le\! e(F(t),F(s))\!+\!e(F(s),F(t_0))$,
we~find
  \begin{align*}
\xi+\ori{v}(t_m)-{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T)\le\xi&<e(F(t),F(s))+{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{[s,t_m]})\\[2pt]
&=e(F(t),F(s))+\ori{v}(t_m)-\ori{v}(s),
  \end{align*}
and so, $\ori{v}(s)\le({\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T)-\xi)+e(F(t),F(s))$. Passing to the limit superior as
$T\ni s\to t+0$, we get
  \begin{equation*}
\ori{v}(t+0)\le{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T)-\xi+\limsup_{T\ni s\to t+0}e(F(t),F(s)).
  \end{equation*}
It remains to let $\xi$ tend to the value \mbox{\rm(\ref{e:tin})}.

($\ori{\mbox{\rm b}}$)
In order to prove inequality $\ge$ in ($\ori{\mbox{\rm b}}$), we make use of the
additivity of ${\scriptstyle\overrightarrow{\mbox{\rm V}}}$ to get
  \begin{equation*}
\ori{v}(t)+e(F(t),F(s))\le\ori{v}(t)+{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{[t,s]})=\ori{v}(s)\quad
\mbox{for all $s\in T_{(t,+\infty)}$.}
  \end{equation*}
Now, it suffices to pass to the limit superior as $T\ni  s\to t+0$.

To show inequality $\le$ in ($\ori{\mbox{\rm b}}$), we apply the additivity property
of ${\scriptstyle\overrightarrow{\mbox{\rm V}}}$ several times. To begin with, note that
  \begin{equation} {\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{[t,+\infty)})={\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T)-\ori{v}(t).
  \end{equation}
Given $\xi\in\mathbb{R}$ with $\xi<{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{[t,+\infty)})$, there exist $m\in\mathbb{N}$ and a
partition $\{t\}\cup\{t_i\}_{i=0}^m$ of $T_{[t,+\infty)}$ with $t<t_0$ such that
  \begin{equation*}
\xi<e(F(t),F(t_0))+\sum_{i=1}^m e(F(t_{i-1}),F(t_i)).
  \end{equation*}
Since, for any $s\!\in\! T_{(t,t_0)}$, $e(F(t),F(t_0))\!\le\! e(F(t),F(s))\!+\!e(F(s),F(t_0))$,
we~find
  \begin{align*}
\xi+\ori{v}(t_m)-{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T)\le\xi&<e(F(t),F(s))+{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{[s,t_m]})\\[2pt]
&=e(F(t),F(s))+\ori{v}(t_m)-\ori{v}(s),
  \end{align*}
and so, $\ori{v}(s)\le({\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T)-\xi)+e(F(t),F(s))$. Passing to the limit superior as
$T\ni s\to t+0$, we get
  \begin{equation*}
\ori{v}(t+0)\le{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T)-\xi+\limsup_{T\ni s\to t+0}e(F(t),F(s)).
  \end{equation*}
It remains to let $\xi$ tend to the value \mbox{\rm(\ref{e:tin})}.

Given $\xi\in\mathbb{R}$ with $\xi<{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{[t,+\infty)})$, there exist $m\in\mathbb{N}$ and a
partition $\{t\}\cup\{t_i\}_{i=0}^m$ of $T_{[t,+\infty)}$ with $t<t_0$ such that
  \begin{equation*}
\xi<e(F(t),F(t_0))+\sum_{i=1}^m e(F(t_{i-1}),F(t_i)).
  \end{equation*}

Passing to the limit superior as
$T\ni s\to t+0$, we get
  \begin{equation*}
\ori{v}(t+0)\le{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T)-\xi+\limsup_{T\ni s\to t+0}e(F(t),F(s)).
  \end{equation*}
It remains to let $\xi$ tend to the value \mbox{\rm(\ref{e:tin})}.

($\ori{\mbox{\rm a}}$) This is a consequence of Lemma~\ref{l:jumps}
($\ori{\mbox{\rm a}}$), since ${\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{(-\infty,t]})=\ori{v}(t)$ and,
by virtue of \mbox{\rm(\ref{e:ttos})}, ${\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{(-\infty,t)})=\ori{v}(t-0)$.

($\ori{\mbox{\rm b}}$) For every $s\in T_{(t,+\infty)}$, the additivity of ${\scriptstyle\overrightarrow{\mbox{\rm V}}}$ implies
  \begin{equation*}
{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{[t,+\infty)})=\ori{v}(s)-\ori{v}(t)+{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{[s,+\infty)}).
  \end{equation*}
Passing to the limit as $T\ni s\to t+0$, we get: by Lemma~\ref{l:jumps}
($\ori{\mbox{\rm b}}$),
  \begin{equation*}
\ori{v}(s)-\ori{v}(t)\to\ori{v}(t+0)-\ori{v}(t)=\limsup_{T\ni s\to t+0}e(F(t),F(s)),
  \end{equation*}
and by \mbox{\rm(\ref{e:ttoi})}, ${\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{[s,+\infty)})\to{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{(t,+\infty)})$.
\qed

{\it Step~2}. Let us construct an approximating sequence for the desired set-valued
selector of $F$. In order to do this, we need the following observation from
\cite[assertion (10.2)]{Sovae}: given $X,Y\in\mbox{c}(M)$,
  \begin{equation} \mbox{there is $Y'\in\mbox{c}(M)$ such that $Y'\subset Y$ and
$d_H(X,Y')\le e(X,Y)$.}
  \end{equation}

In fact, it suffices to define $Y'$ as the \emph{metric projection\/} of $X$ onto~$Y$:
  \begin{equation} Y'=\mbox{\rm Pr}_Y X:=\{y\in Y:\mbox{there is $x\in X$ such that $d(x,y)=d(x,Y)$}\}.
  \end{equation}

The approximating sequence $\Gamma_n:T\to\mbox{c}(M)$, $n\in\mathbb{N}$, is defined as
a sequence of set-valued step functions of the form (cf. \cite[equation~(10.3)]{Sovae}):
  \begin{align}
\Gamma_n(t_i^n)&:=Y_i^n\quad\mbox{for all \,$i=0,1,\dots,n;$} \\[2pt]
\Gamma_n(t)&:=Y_{i-1}^n\,\,\,\mbox{for all $t\in T\cap(t_{i-1}^n,t_i^n)$
  and $i=1,\dots,n$} \end{align}
(if $T\cap(t_{i-1}^n,t_i^n)=\varnothing$, then $\Gamma_n$ is left undefined
on $(t_{i-1}^n,t_i^n)$). Clearly,
  \begin{equation*}
\Gamma_n(t_0)=\Gamma_n(t_0^n)=Y_0^n=Y_0\subset F(t_0)\quad
\mbox{for all \,$n\in\mathbb{N}$.}
  \end{equation*}

Moreover, by the additivity of $\mbox{\rm V}$ and \mbox{\rm(\ref{e:Yin})}, we have
  \begin{align}
\mbox{\rm V}(\Gamma_n,T)&=\sum_{i=1}^n\mbox{\rm V}(\Gamma_n,T\cap[t_{i-1}^n,t_i^n])
  =\sum_{i=1}^n d_H(Y_{i-1}^n,Y_i^n)\nonumber\\
&\le\sum_{i=1}^n e(F(t_{i-1}^n),F(t_i^n))\le{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T)
  \quad\mbox{for all $n\in\mathbb{N}$.} \end{align}

{\it Step~3}. Let us show that $\{\Gamma_n\}_{n=1}^\infty$ satisfies the assumptions
of Theorem~\ref{t:B}. By virtue of \mbox{\rm(\ref{e:gn})}, we get
  \begin{equation*}
\limsup_{n\to\infty}\nu_k(\Gamma_n,T)\le{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T)\quad\mbox{for all \,$k\in\mathbb{N}$,}
  \end{equation*}
and so, condition (a) in Theorem~\ref{t:B} is satisfied. Now, we verify condition~(b).

By virtue of \mbox{\rm(\ref{e:gn})}, we get
  \begin{equation*}
\limsup_{n\to\infty}\nu_k(\Gamma_n,T)\le{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T)\quad\mbox{for all \,$k\in\mathbb{N}$,}
  \end{equation*}
and so, condition (a) in Theorem~\ref{t:B} is satisfied.

It remains to show that if $s_0=t_0$, then $J_a(\Gamma,t_0)$ is the left jump of
$\Gamma$ at~$t_0$.\linebreak
Noting that, by the additivity of $\mbox{\rm V}$,
  \begin{equation*}
\mbox{\rm V}(\Gamma,T_{[t,t_0]})=\ori{v}(t_0)-\ori{v}(t)\quad\mbox{for all \,$t\in T_{[a,t_0)}$,}
  \end{equation*}
and, by \mbox{\rm(\ref{e:VFtm})},
  \begin{equation*}
\ori{v}(t_0)=\ori{v}(t_0-0)+\lim_{T\ni t\to t_0-0}d_H(\Gamma(t),\Gamma(t_0)),
  \end{equation*}
and passing to the limit as $T\ni t\to t_0-0$, we get
  \begin{align*}
J_a(\Gamma,t_0)&=\lim_{T\ni t\to t_0-0}\mbox{\rm V}(\Gamma,T_{[t,t_0]})
  =\ori{v}(t_0)-\lim_{T\ni t\to t_0-0}\ori{v}(t)\\
&=\ori{v}(t_0-0)+\lim_{T\ni t\to t_0-0}d_H(\Gamma(t),\Gamma(t_0))-\ori{v}(t_0-0)\\
&=\lim_{T\ni t\to t_0-0}d_H(\Gamma(t),\Gamma(t_0)).
  \end{align*}

This completes the proof of Theorem~\ref{t:BV}.
\qed

Setting $T_+=T_{[t_0,+\infty)}$ and $T_-=T_{(-\infty,t_0]}$, we have
  \begin{equation*}
{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_+)\le\mbox{\rm V}(F,T_+)\le\mbox{\rm V}(F,T)\quad\mbox{and}\quad
  {\scriptstyle\overleftarrow{\mbox{\rm V}}}(F,T_-)\le\mbox{\rm V}(F,T_-)\le\mbox{\rm V}(F,T).
  \end{equation*}

First, observe that assumptions (a) and (b) and the triangle inequality for $e$ imply,
for all $s,t\in T$, $s\le t$, and $X,Y\in\mbox{c}(M)$,
  \begin{equation} e(F(s,X),F(t,Y))\le\varphi(t)-\varphi(s)+\mu d_H(X,Y).
  \end{equation}

In what follows we apply the standard
iteration procedure. Setting $F_1(t):=F(t,X_1(t))$ for $t\in T$, we find
$F_1:T\to\mbox{c}(M)$ and, by \mbox{\rm(\ref{e:XY})},
  \begin{equation*}
e(F_1(s),F_1(t))\le\varphi(t)-\varphi(s)+\mu d_H(X_1(s),X_1(t))\quad
  \forall\,s,t\in T,\,\,s\le t.
  \end{equation*}
Arguing with partitions of $T$, Lemma~\ref{l:char} implies
  \begin{equation*}
{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F_1,T)\le\mbox{\rm V}(\varphi,T)+\mu\mbox{\rm V}(X_1,T)\le(1+\mu)\mbox{\rm V}(\varphi,T).
  \end{equation*}

Applying Theorem~\ref{t:BV} again, we obtain $X_2:T\to\mbox{c}(M)$ such that
$X_2(t)\subset F_1(t)$ for all $t\in T$, $d_H(X_0,X_2(t_0))\le e(X_0,F_1(t_0))$, and
  \begin{equation*}
\mbox{\rm V}(X_2,T)\le{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F_1,T)\le(1+\mu)\mbox{\rm V}(\varphi,T).
  \end{equation*}
If $F_2(t)\!:=\!F(t,X_2(t))$, $t\in T$, then $F_2:T\to\mbox{c}(M)$ and, by \mbox{\rm(\ref{e:XY})},
  \begin{equation*}
e(F_2(s),F_2(t))\le\varphi(t)-\varphi(s)+\mu d_H(X_2(s),X_2(t))\quad
  \forall\,s,t\in T,\,\,s\le t,
  \end{equation*}
and so,
  \begin{equation*}
{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F_2,T)\le\mbox{\rm V}(\varphi,T)+\mu\mbox{\rm V}(X_2,T)\le(1+\mu+\mu^2)\mbox{\rm V}(\varphi,T).
  \end{equation*}

To establish (iii), we note that (cf. \mbox{\rm(\ref{e:Hot})} and (iii))
  \begin{equation*}
|d_H(X_0,X_n(t_0))-d_H(X_0,X(t_0))|\le d_H(X_n(t_0),X(t_0))\to0
  \,\,\,\,\mbox{as}\,\,\,n\to\infty,
  \end{equation*}
and, by virtue of \mbox{\rm(\ref{e:Sog})} and assumption (b),
  \begin{align*}
&\qquad\bigl|e(X_0,F(t_0,X_{n-1}(t_0)))-e(X_0,F(t_0,X(t_0)))\bigr|\\[2pt]
\le&\,d_H(F(t_0,X_{n-1}(t_0)),F(t_0,X(t_0)))\le\mu d_H(X_{n-1}(t_0),X(t_0))
  \to0,\,\,n\to\infty.
  \end{align*}
Passing to the limit as $n\to\infty$ in \mbox{\rm(\ref{e:Hot})}, we arrive at~(iii).
